#!/usr/bin/env bash
# Detector `no-free-validator` for [R:parse-dont-validate], generated by relearn from the rule file.
# Edit the rule, never this script: `relearn verify` reports a hand edit.
# Engine: line-regex. Event: Claude Code PreToolUse, on Write|Edit|MultiEdit.
# Exit 2 blocks, and stderr is the reason Claude reads. Exit 0 allows.
# Any other exit is this script failing: reported, never a block.
set -uo pipefail
export LC_ALL=C

name='no-free-validator'
tag='R:parse-dont-validate'
message='A validator that returns bool or Result<()> checks and then throws the proof away, so every interior caller must check again or trust that someone did. Parse instead: return the witness newtype, so holding one is the proof.'
files_ere='((^|/)([^/]+/)*[^/]*\.rs$)'
exclude_ere='((^|/)([^/]+/)*tests/.*$)|((^|/)([^/]+/)*benches/.*$)|((^|/)([^/]+/)*examples/.*$)|((^|/)([^/]+/)*tests\.rs$)|((^|/)([^/]+/)*[^/]*_test\.rs$)|((^|/)([^/]+/)*[^/]*_tests\.rs$)|((^|/)([^/]+/)*rules/[^/]*\.md$)|((^|/)([^/]+/)*hooks-pack/.*$)|((^|/)([^/]+/)*repo-pack/.*$)|((^|/)([^/]+/)*hooks/relearn/.*$)'

fail() {
  printf '[%s] %s; the detector did not run.\n' "$name" "$1" >&2
  exit 1
}
command -v jq >/dev/null 2>&1 || fail "jq is not on PATH"

input="$(cat)"
tool_name="$(jq -r '.tool_name // ""' <<<"$input")" || fail "the payload is not JSON"
case "$tool_name" in Write|Edit|MultiEdit) ;; *) exit 0 ;; esac
file_path="$(jq -r '.tool_input.file_path // ""' <<<"$input")" || fail "the payload has no readable file_path"
file_path="${file_path//\\//}"
[ -n "$file_path" ] || exit 0

# Scope: one ERE per list, compiled by relearn from the rule's globs.
printf '%s\n' "$file_path" | grep -qE -- "$files_ere"
case $? in 0) ;; 1) exit 0 ;; *) fail "grep could not read the files pattern" ;; esac
printf '%s\n' "$file_path" | grep -qE -- "$exclude_ere"
case $? in 0) exit 0 ;; 1) ;; *) fail "grep could not read the exclude pattern" ;; esac

pattern='\bfn (validate|is_valid)[a-z0-9_]*[[:space:]]*(<[^>]*>)?\([^)]*\)[[:space:]]*->[[:space:]]*(bool|Result<\(\),)'
case "$tool_name" in
  Write) new="$(jq -r '.tool_input.content // ""' <<<"$input")" ;;
  Edit) new="$(jq -r '.tool_input.new_string // ""' <<<"$input")" ;;
  MultiEdit) new="$(jq -r '[.tool_input.edits[]?.new_string] | join("\n")' <<<"$input")" ;;
esac || fail "the payload's text could not be read"

hits="$(printf '%s\n' "$new" | grep -nE -- "$pattern")"
case $? in 0) ;; 1) exit 0 ;; *) fail "grep could not read the pattern" ;; esac
# A line whose first non-blank text is '//' is a comment, not code.
hits="$(printf '%s\n' "$hits" | grep -vE -- '^[0-9]+:[[:space:]]*//')"
# A line carrying 'allow:validator' is a deliberate, marked exception.
hits="$(printf '%s\n' "$hits" | grep -vF -- 'allow:validator')"
[ -n "$hits" ] || exit 0

{
  printf '[%s] %s: BLOCKED. %s\n' "$tag" "$name" "$message"
  printf 'Offending line(s) in %s:\n%s\n' "$file_path" "$hits"
  printf 'A deliberate exception is marked on its own line with: %s\n' 'allow:validator'
} >&2
exit 2

